tasks = { ["Raise your leatherworking skill to 20"] = [===[Підвищити навичку шкірництва до 20]===] },
},
[97907] = { en="Camping 101: Mining", ai=true,
[===[Основи таборування: гірництво]===],
[===[Гірництво - не найблискучіша справа, але це добра чесна праця і чудова професія, яку варто спробувати.

