[97908] = { en="Camping 101: Skinning", ai=true,
[===[Основи таборування: шкуродерство]===],
[===[Уміння вправно знімати шкури й шкіри з полеглих звірів — одна з найцінніших навичок, якою може володіти шукач пригод.

